/* ── small helpers ─────────────────────────────────────────────── */
function arcPoints(cx, cy, r, a0, a1) {
  var n = Math.max(10, Math.round(Math.abs(a1 - a0) / 0.06)), s = [];
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * i / n;
    s.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy - r * Math.sin(a)).toFixed(2));
  }
  return s.join(' ');
}

function lab(g, x, y, txt, size, anchor) {
  var t = g.plain(txt);
  t.font({ family: SERIF, size: size, style: 'italic' });
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'middle',
    fill: '#000', 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.4,
    'stroke-linejoin': 'round', 'pointer-events': 'none'
  });
  return t;
}

function hit(el, tip, title, body, onClick) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () {
    hideTooltip();
    if (onClick) onClick();
    if (title) showPopup(title, body);
  });
}

function panelInfo(t, L, hh) {
  var th = Math.atan2(hh, t * L);
  var unit = 10 / L;
  return {
    adeg: th * 180 / Math.PI,
    c: Math.sqrt(t * L * t * L + hh * hh) * unit,
    h: hh * unit,
    area: 0.5 * 10 * hh * unit
  };
}

/* ── one triangle panel ────────────────────────────────────────── */
function drawPanel(o) {
  var g = figDraw.group();
  var ax = o.ax, ay = o.ay, L = o.L, hh = o.hh, t = o.t, fs = o.fs, sw = 1.5;
  var A = { x: ax, y: ay }, C = { x: ax + L, y: ay };
  var B = { x: ax + t * L, y: ay - hh }, F = { x: ax + t * L, y: ay };
  var obtuse = t < -0.005;
  var th = Math.atan2(hh, t * L);
  var info = panelInfo(t, L, hh);
  var sinA = Math.sin(th);

  /* shaded embedded right triangle */
  if (o.hl && o.alt && Math.abs(t) > 0.01) {
    g.polygon([[A.x, A.y], [F.x, F.y], [B.x, B.y]])
      .fill({ color: ACCENT, opacity: 0.18 }).stroke('none');
  }

  /* dashed base extension (obtuse case only) */
  if (obtuse && o.alt) {
    g.line(A.x, A.y, F.x - 12, F.y)
      .stroke({ color: '#000', width: sw, dasharray: '6,4', linecap: 'butt' });
  }

  /* dashed altitude */
  if (o.alt) {
    g.line(B.x, B.y, F.x, F.y)
      .stroke({ color: '#000', width: sw, dasharray: '6,4', linecap: 'butt' });
  }

  /* triangle outline */
  g.polygon([[A.x, A.y], [B.x, B.y], [C.x, C.y]])
    .fill('none').stroke({ color: '#000', width: sw, linejoin: 'round' });

  /* right-angle marker */
  if (o.alt && Math.abs(t) > 0.015) {
    var s = Math.max(9, L * 0.028);
    var dir = obtuse ? 1 : -1;
    g.polyline([[F.x + dir * s, F.y], [F.x + dir * s, F.y - s], [F.x, F.y - s]])
      .fill('none').stroke({ color: '#000', width: 1.2 });
  }

  /* angle arcs */
  var r = 0.088 * L;
  var arcA = g.polyline(arcPoints(A.x, A.y, r, 0, th))
    .fill('none').stroke({ color: '#000', width: 1.2 });
  hit(arcA, 'interior angle α = ' + info.adeg.toFixed(1) + '°',
    'The angle α', 'α is the angle of the triangle at the vertex α, between side c and base b. When α passes 90° the altitude from β no longer lands on the base segment.');

  var arcP = null;
  if (obtuse && o.aprime) {
    var r2 = r * 0.62;
    arcP = g.polyline(arcPoints(A.x, A.y, r2, th, Math.PI))
      .fill('none').stroke({ color: '#000', width: 1.2 });
    hit(arcP, "α′ = 180° − α = " + (180 - info.adeg).toFixed(1) + '°',
      'The exterior angle α′',
      "α′ is the angle between side c and the dashed extension of the base — the angle that actually sits in the right triangle. Because sin(180° − α) = sin α, we get h = c·sin α′ = c·sin α.");
  }

  /* invisible hit strips on the sides */
  var hitStroke = { color: '#000', width: 16, opacity: 0 };
  var hb = g.line(A.x, A.y, C.x, C.y).stroke(hitStroke);
  hit(hb, 'base b — click to drop the altitude from β', 'The base b',
    'The height of a triangle is measured to the LINE containing the base, not to the base segment. Dropping the perpendicular from β gives h, and the area is ½·b·h.',
    function () {
      document.getElementById('buildAltitudeInput').checked = true;
      document.getElementById('highlightInput').checked = true;
      ST.alt = true; ST.hl = true; render();
    });

  var hc = g.line(A.x, A.y, B.x, B.y).stroke(hitStroke);
  hit(hc, 'side c = ' + info.c.toFixed(2) + ' units', 'Side c',
    'Side c is the hypotenuse of the right triangle that contains the altitude. Its leg opposite the angle at α is h, so h = c·sin α.');

  var ha = g.line(B.x, B.y, C.x, C.y).stroke(hitStroke);
  hit(ha, 'side a — opposite the angle at α', 'Side a',
    'Side a faces the vertex α. Combining h = c·sin α with h = a·sin γ gives the law of sines a/sin α = c/sin γ.');

  if (o.alt) {
    var hh2 = g.line(B.x, B.y, F.x, F.y).stroke(hitStroke);
    hit(hh2, 'altitude h = c·sin α = ' + info.h.toFixed(2), 'The altitude h',
      'h is perpendicular to the base line. In the acute case the right triangle uses α; in the obtuse case it uses α′ = 180° − α. Since the sines are equal, h = c·sin α in both cases.');
  }

  /* labels (drawn last, with white halo) */
  var dxw = t * L, dyw = hh;
  var nlen = Math.sqrt(dxw * dxw + dyw * dyw) || 1;
  var nx = -dyw / nlen, ny = dxw / nlen;
  if (t < 0) { nx = -nx; ny = -ny; }
  var cm = { x: (A.x + B.x) / 2, y: (A.y + B.y) / 2 };
  lab(g, cm.x + nx * 22, cm.y - ny * 22, 'c', fs);

  var dax = L - dxw, day = -hh;
  var alen = Math.sqrt(dax * dax + day * day) || 1;
  var anx = hh / alen, any = (L - dxw) / alen;
  var am = { x: (B.x + C.x) / 2, y: (B.y + C.y) / 2 };
  lab(g, am.x + anx * 22, am.y - any * 22, 'a', fs);

  lab(g, ax + L / 2, ay + 26, 'b', fs);

  if (o.alt) {
    var hy = ay - hh * 0.55;
    if (obtuse) lab(g, F.x - 13, hy, 'h', fs, 'end');
    else lab(g, F.x + 13, hy, 'h', fs, 'start');
  }

  lab(g, B.x, B.y - 16, 'β', fs + 1);
  lab(g, C.x + 14, C.y - 7, 'γ', fs + 1, 'start');

  if (obtuse) {
    var rl = r + 20;
    lab(g, A.x + rl * Math.cos(th / 2), A.y - rl * Math.sin(th / 2), 'α', fs + 1);
    if (o.aprime) {
      var mid = (th + Math.PI) / 2, rp = r * 0.62 + 17;
      lab(g, A.x + rp * Math.cos(mid), A.y - rp * Math.sin(mid), 'α′', fs + 1);
    }
  } else {
    lab(g, A.x - 14, A.y - 7, 'α', fs + 1, 'end');
  }
  return g;
}

/* ── render ────────────────────────────────────────────────────── */
function render() {
  figDraw.clear();
  figDraw.rect(VW, VH).fill('#ffffff').stroke('none');
  if (ST.mode === 'both') {
    var m = Math.max(0.12, Math.abs(ST.t));
    drawPanel({ ax: 90, ay: 250, L: 345, hh: 170, t: m, fs: 17, alt: ST.alt, hl: ST.hl, aprime: ST.aprime });
    drawPanel({ ax: 580, ay: 250, L: 345, hh: 170, t: -Math.max(0.05, m * 0.25), fs: 17, alt: ST.alt, hl: ST.hl, aprime: ST.aprime });
  } else {
    drawPanel({ ax: 360, ay: 256, L: 470, hh: 198, t: ST.t, fs: 19, alt: ST.alt, hl: ST.hl, aprime: ST.aprime });
  }
  updateReadout();
}

function fmtPanel(name, t, L, hh) {
  var i = panelInfo(t, L, hh);
  var a = i.adeg, s = Math.sin(a * Math.PI / 180);
  var out = '<b>' + name + '</b><br>α = ' + a.toFixed(1) + '°';
  if (a > 90.05) out += ' &nbsp; α′ = ' + (180 - a).toFixed(1) + '°';
  out += '<br>sin α = ' + s.toFixed(3) + (a > 90.05 ? ' = sin α′' : '');
  out += '<br>h = c·sin α = ' + i.c.toFixed(2) + '×' + s.toFixed(3) + ' = ' + i.h.toFixed(2);
  out += '<br>area = ½·b·h = ' + i.area.toFixed(2) + ' &nbsp;(b = 10)';
  return out;
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  if (ST.mode === 'both') {
    var m = Math.max(0.12, Math.abs(ST.t));
    el.innerHTML = fmtPanel('Acute case (left)', m, 345, 170) + '<br><br>' +
      fmtPanel('Obtuse case (right)', -Math.max(0.05, m * 0.25), 345, 170);
  } else {
    el.innerHTML = fmtPanel(ST.t < 0 ? 'Obtuse at α' : 'Acute at α', ST.t, 470, 198);
  }
}

/* ── interactions ──────────────────────────────────────────────── */
function update_apexPosition(v) {
  ST.t = v;
  if (ST.mode !== 'both') {
    ST.mode = (v < -0.005) ? 'obtuse' : 'acute';
    document.getElementById('caseViewInput').value = ST.mode;
  }
  render();
}

function toggle_caseView(v) {
  ST.mode = v;
  if (v === 'acute' && ST.t < 0.05) setSlider(0.35);
  if (v === 'obtuse' && ST.t > -0.05) setSlider(-0.35);
  if (v === 'obtuse') { ST.alt = true; document.getElementById('buildAltitudeInput').checked = true; }
  render();
}

function toggle_buildAltitude(on) { ST.alt = on; render(); }
function toggle_highlight(on) { ST.hl = on; render(); }

function trigger_buildAltitude() {
  ST.alt = true; ST.hl = true;
  document.getElementById('buildAltitudeInput').checked = true;
  document.getElementById('highlightInput').checked = true;
  render();
