  var u = 10 / G.L;
  return {
    adeg: th * 180 / Math.PI,
    c: Math.sqrt(G.t * G.L * G.t * G.L + G.hh * G.hh) * u,
    h: G.hh * u,
    area: 0.5 * 10 * G.hh * u
