// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

var SERIF = 'Georgia, "Times New Roman", serif';
var ACCENT = '#5b9bd5';
var VW = 960, VH = 300;

var ST = { t: 0.35, mode: 'both', alt: true, hl: false, aprime: true };
var panelsState = [];

var STEPS = [
  {
    title: 'The construction',
    nar: 'Two oblique triangles with identical lettering. In each one a dashed perpendicular h drops from the apex β to the line containing the base b. On the left the foot lands on b; on the right it lands outside, on a dashed extension of b.',
    st: { mode: 'both', t: 0.35, alt: true, hl: false, aprime: true }
  },
  {
    title: 'An oblique triangle',
    nar: 'A triangle with base b from α to γ and apex β — no right angle anywhere. To find its area we still need a height.',
    st: { mode: 'acute', t: 0.35, alt: false, hl: false, aprime: false }
  },
  {
    title: 'Drop the altitude',
    nar: 'Click on base b: a dashed perpendicular h falls from β and a small square marks the right angle. The oblique triangle now contains a right triangle with legs h and part of b.',
    st: { mode: 'acute', t: 0.35, alt: true, hl: true, aprime: false }
  },
  {
    title: 'Slide β toward α',
    nar: 'Drag the apex left. The foot of the altitude travels along the base toward α while h stays perpendicular to the base line.',
    st: { mode: 'acute', t: 0.06, alt: true, hl: true, aprime: false }
  },
  {
    title: 'Past α: the foot leaves the triangle',
    nar: 'When β passes to the left of α, the angle at α becomes obtuse and the altitude foot lands off the base — the base line must be extended by a dashed segment to catch it.',
    st: { mode: 'obtuse', t: -0.3, alt: true, hl: true, aprime: false }
  },
  {
    title: 'The angle α′ adjacent to the perpendicular',
    nar: 'In the obtuse case two arcs appear: the interior angle α and its supplement α′ between c and the extension. It is α′ that sits in the right triangle, and sin α′ = sin α, so h = c·sin α either way.',
    st: { mode: 'obtuse', t: -0.3, alt: true, hl: true, aprime: true }
  },
  {
    title: 'Compare both cases',
    nar: 'Seen side by side, the two constructions are the same move: drop a perpendicular from β to the line containing b. Only whether the foot lands inside or outside the triangle differs.',
    st: { mode: 'both', t: -0.3, alt: true, hl: true, aprime: true }
  }
];
var stepIdx = 0;

/* ── helpers ───────────────────────────────────────────────────── */
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function arcPoints(cx, cy, r, a0, a1) {
  var n = Math.max(12, Math.round(Math.abs(a1 - a0) / 0.05)), s = [];
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * i / n;
    s.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy - r * Math.sin(a)).toFixed(2));
  }
  return s.join(' ');
}

function lab(g, x, y, txt, size, anchor) {
  var t = g.plain(txt);
  t.font({ family: SERIF, size: size, style: 'italic' });
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'middle',
    fill: '#000', 'paint-order': 'stroke', stroke: '#ffffff',
    'stroke-width': Math.max(2, size * 0.22), 'stroke-linejoin': 'round',
    'pointer-events': 'none'
  });
  return t;
}

function hit(el, tip, title, body, onClick) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () {
    hideTooltip();
    if (onClick) onClick();
    if (title) showPopup(title, body);
  });
}

/* ── layout: geometry derived from the real canvas size ────────── */
function tAcute() { return clamp(Math.abs(ST.t) < 0.2 ? 0.2 : Math.abs(ST.t), 0.2, 1); }
function tObtuse() { return -clamp(Math.max(0.16, Math.abs(ST.t) * 0.65), 0.16, 0.45); }

function geom(bx, by, bw, bh, t) {
  var fs = clamp(Math.min(bw * 0.040, bh * 0.135), 10, 24);
  var mL = fs * 1.9, mR = fs * 2.1, mT = fs * 2.1, mB = fs * 2.5;
  var AW = Math.max(40, bw - mL - mR);
  var AH = Math.max(30, bh - mT - mB);
  var ext = Math.max(0, -t);
  var L = AW / (1 + ext);
  var hh = Math.min(L * 0.55, AH);
  var UW = L * (1 + ext);
  var ax = bx + mL + (AW - UW) / 2 + ext * L;
  var ay = by + bh - mB - (AH - hh) / 2;
  return {
    fs: fs, L: L, hh: hh, t: t,
    A: { x: ax, y: ay },
    C: { x: ax + L, y: ay },
    B: { x: ax + t * L, y: ay - hh },
    F: { x: ax + t * L, y: ay }
  };
}

function layout(W, H) {
  if (ST.mode === 'both') {
    if (W / H >= 1.7) {
      return [geom(0, 0, W / 2, H, tAcute()), geom(W / 2, 0, W / 2, H, tObtuse())];
    }
    return [geom(0, 0, W, H / 2, tAcute()), geom(0, H / 2, W, H / 2, tObtuse())];
  }
  return [geom(0, 0, W, H, ST.t)];
}

/* ── info in abstract units (base b = 10) ──────────────────────── */
function panelInfo(G) {
  var th = Math.atan2(G.hh, G.t * G.L);
  var u = 10 / G.L;
  return {
    adeg: th * 180 / Math.PI,
    c: Math.sqrt(G.t * G.L * G.t * G.L + G.hh * G.hh) * u,
    h: G.hh * u,
    area: 0.5 * 10 * G.hh * u
  };
}

/* ── one triangle panel ────────────────────────────────────────── */
function drawPanel(G) {
  var g = figDraw.group();
  var A = G.A, B = G.B, C = G.C, F = G.F, L = G.L, hh = G.hh, t = G.t, fs = G.fs;
  var sw = Math.max(1, fs * 0.085);
  var dash = (fs * 0.38).toFixed(1) + ',' + (fs * 0.28).toFixed(1);
  var obtuse = t < -0.005;
  var th = Math.atan2(hh, t * L);
  var info = panelInfo(G);

  /* shaded embedded right triangle */
  if (ST.hl && ST.alt && Math.abs(t) > 0.012) {
    g.polygon([[A.x, A.y], [F.x, F.y], [B.x, B.y]])
      .fill({ color: ACCENT, opacity: 0.18 }).stroke('none');
  }

  /* dashed base extension (obtuse only) */
  if (obtuse && ST.alt) {
    g.line(A.x, A.y, F.x, F.y)
      .stroke({ color: '#000', width: sw, dasharray: dash, linecap: 'butt' });
  }

  /* dashed altitude */
  if (ST.alt) {
    g.line(B.x, B.y, F.x, F.y)
      .stroke({ color: '#000', width: sw, dasharray: dash, linecap: 'butt' });
  }

  /* triangle outline */
  g.polygon([[A.x, A.y], [B.x, B.y], [C.x, C.y]])
    .fill('none').stroke({ color: '#000', width: sw, linejoin: 'round' });

  /* right-angle marker at the foot */
  var s = fs * 0.62;
  if (ST.alt && Math.abs(t) * L > s * 1.7) {
    var dir = obtuse ? 1 : -1;
    g.polyline([[F.x + dir * s, F.y], [F.x + dir * s, F.y - s], [F.x, F.y - s]])
      .fill('none').stroke({ color: '#000', width: sw * 0.8 });
  }

  /* angle arcs at α */
  var r = Math.min(L * 0.135, hh * 0.42);
  var arcA = g.polyline(arcPoints(A.x, A.y, r, 0, th))
    .fill('none').stroke({ color: '#000', width: sw * 0.8 });
  hit(arcA, 'interior angle α = ' + info.adeg.toFixed(1) + '°', 'The angle α',
    'α is the angle of the triangle at the vertex α, between side c and base b. When α passes 90° the altitude from β no longer lands on the base segment.');

  var r2 = r * 0.66;
  if (obtuse && ST.aprime) {
    var arcP = g.polyline(arcPoints(A.x, A.y, r2, th, Math.PI))
      .fill('none').stroke({ color: '#000', width: sw * 0.8 });
    hit(arcP, "α′ = 180° − α = " + (180 - info.adeg).toFixed(1) + '°', 'The exterior angle α′',
      "α′ is the angle between side c and the dashed extension of the base — the angle that actually sits in the right triangle. Because sin(180° − α) = sin α, we get h = c·sin α′ = c·sin α.");
  }

  /* invisible hit strips on the sides */
  var hitStroke = { color: '#000', width: Math.max(12, fs * 0.95), opacity: 0 };

  var hb = g.line(A.x, A.y, C.x, C.y).stroke(hitStroke);
  hit(hb, 'base b — click to drop the altitude from β', 'The base b',
    'The height of a triangle is measured to the LINE containing the base, not to the base segment. Dropping the perpendicular from β gives h, and the area is ½·b·h.',
    function () {
      document.getElementById('buildAltitudeInput').checked = true;
      document.getElementById('highlightInput').checked = true;
      ST.alt = true; ST.hl = true; render();
    });

  var hc = g.line(A.x, A.y, B.x, B.y).stroke(hitStroke);
  hit(hc, 'side c = ' + info.c.toFixed(2) + ' units', 'Side c',
    'Side c is the hypotenuse of the right triangle that contains the altitude. Its leg opposite the angle at α (or α′) is h, so h = c·sin α.');

  var ha = g.line(B.x, B.y, C.x, C.y).stroke(hitStroke);
  hit(ha, 'side a — opposite the angle at α', 'Side a',
    'Side a faces the vertex α. Combining h = c·sin α with h = a·sin γ gives the law of sines a/sin α = c/sin γ.');

  if (ST.alt) {
    var hhit = g.line(B.x, B.y, F.x, F.y).stroke(hitStroke);
    hit(hhit, 'altitude h = c·sin α = ' + info.h.toFixed(2), 'The altitude h',
      'h is perpendicular to the base line. In the acute case the right triangle uses α; in the obtuse case it uses α′ = 180° − α. Since the sines are equal, h = c·sin α in both cases.');
  }

  /* ── labels (drawn last, white halo, collision-aware offsets) ── */
  var off = fs * 1.15;

  /* c : outside the triangle when acute, toward the interior when obtuse */
  var dx = B.x - A.x, dy = B.y - A.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var px = -dy / len, py = dx / len;            /* one perpendicular */
  var towardC = (C.x - (A.x + B.x) / 2) * px + (C.y - (A.y + B.y) / 2) * py;
  var sgn = obtuse ? (towardC > 0 ? 1 : -1) : (towardC > 0 ? -1 : 1);
  var cmx = (A.x + B.x) / 2 + sgn * px * off;
  var cmy = (A.y + B.y) / 2 + sgn * py * off;
  if (obtuse) cmy = A.y - hh * 0.48;
  lab(g, cmx, cmy, 'c', fs);

  /* a : outside the upper-right side */
  var ax2 = C.x - B.x, ay2 = C.y - B.y;
  var alen = Math.sqrt(ax2 * ax2 + ay2 * ay2) || 1;
  var apx = -ay2 / alen, apy = ax2 / alen;
  var towardA2 = (A.x - (B.x + C.x) / 2) * apx + (A.y - (B.y + C.y) / 2) * apy;
  var asg = towardA2 > 0 ? -1 : 1;
  lab(g, (B.x + C.x) / 2 + asg * apx * off, (B.y + C.y) / 2 + asg * apy * off, 'a', fs);

  /* b : below the base */
  lab(g, A.x + L / 2, A.y + fs * 1.5, 'b', fs);

  /* h : right of the altitude when acute, left of it when obtuse */
  if (ST.alt && Math.abs(t) * L > fs * 0.4) {
    var hy = A.y - hh * (obtuse ? 0.62 : 0.55);
    if (obtuse) lab(g, F.x - fs * 0.55, hy, 'h', fs, 'end');
    else lab(g, F.x + fs * 0.55, hy, 'h', fs, 'start');
  }

  /* vertices */
  lab(g, B.x, B.y - fs * 1.0, 'β', fs * 1.05);
  lab(g, C.x + fs * 0.7, C.y - fs * 0.45, 'γ', fs * 1.05, 'start');

  if (obtuse) {
    var rl = r + fs * 0.95;
    lab(g, A.x + rl * Math.cos(th / 2), A.y - rl * Math.sin(th / 2), 'α', fs * 1.05);
    if (ST.aprime) {
      var mid = (th + Math.PI) / 2, rp = r2 + fs * 0.95;
      lab(g, A.x + rp * Math.cos(mid), A.y - rp * Math.sin(mid) - fs * 0.25, 'α′', fs * 1.05);
    }
  } else {
    lab(g, A.x - fs * 0.8, A.y - fs * 0.25, 'α', fs * 1.05, 'end');
  }
  return g;
}

/* ── render ────────────────────────────────────────────────────── */
function canvasSize() {
  var r = (typeof _containerInnerSize === 'function') ? _containerInnerSize() : null;
  var w = (r && r.width) ? r.width : 900;
  var h = (r && r.height) ? r.height : 500;
  return { w: Math.max(200, w), h: Math.max(140, h) };
}

function render() {
  var sz = canvasSize();
  VW = sz.w; VH = sz.h;
  figDraw.viewbox(0, 0, VW, VH);
  figDraw.clear();
  figDraw.rect(VW, VH).fill('#ffffff').stroke('none');
  panelsState = layout(VW, VH);
  for (var i = 0; i < panelsState.length; i++) drawPanel(panelsState[i]);
  updateReadout();
}

function fmtPanel(name, G) {
  var i = panelInfo(G);
  var a = i.adeg, s = Math.sin(a * Math.PI / 180);
  var out = '<b>' + name + '</b><br>α = ' + a.toFixed(1) + '°';
  if (a > 90.05) out += ' &nbsp; α′ = ' + (180 - a).toFixed(1) + '°';
  out += '<br>sin α = ' + s.toFixed(3) + (a > 90.05 ? ' = sin α′' : '');
  out += '<br>h = c·sin α = ' + i.c.toFixed(2) + '×' + s.toFixed(3) + ' = ' + i.h.toFixed(2);
  out += '<br>area = ½·b·h = ' + i.area.toFixed(2) + ' &nbsp;(b = 10)';
  return out;
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el || !panelsState.length) return;
  if (panelsState.length === 2) {
    el.innerHTML = fmtPanel('Acute case', panelsState[0]) + '<br><br>' +
      fmtPanel('Obtuse case', panelsState[1]);
  } else {
    el.innerHTML = fmtPanel(panelsState[0].t < 0 ? 'Obtuse at α' : 'Acute at α', panelsState[0]);
  }
}

/* ── interactions ──────────────────────────────────────────────── */
function update_apexPosition(v) {
  ST.t = v;
  if (ST.mode !== 'both') {
    ST.mode = (v < -0.005) ? 'obtuse' : 'acute';
    document.getElementById('caseViewInput').value = ST.mode;
  }
  render();
}

function toggle_caseView(v) {
  ST.mode = v;
  if (v === 'acute' && ST.t < 0.05) setSlider(0.35);
  if (v === 'obtuse' && ST.t > -0.05) setSlider(-0.3);
  if (v === 'obtuse') { ST.alt = true; document.getElementById('buildAltitudeInput').checked = true; }
  render();
}

function toggle_buildAltitude(on) { ST.alt = on; render(); }
function toggle_highlight(on) { ST.hl = on; render(); }

function trigger_buildAltitude() {
  ST.alt = true; ST.hl = true;
  document.getElementById('buildAltitudeInput').checked = true;
  document.getElementById('highlightInput').checked = true;
  render();
  showPopup('Dropping the altitude',
    'The perpendicular from β meets the line of the base at the foot of the altitude. Its length h is the height used in area = ½·b·h, whether the foot lands on the base segment or on its dashed extension.');
}

function setSlider(v) {
  ST.t = v;
  var inp = document.getElementById('apexPositionInput');
  var out = document.getElementById('apexPositionVal');
  if (inp) inp.value = v;
  if (out) out.value = v;
}

/* ── step player ───────────────────────────────────────────────── */
function goStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  setSlider(s.st.t);
  ST.mode = s.st.mode; ST.alt = s.st.alt; ST.hl = s.st.hl; ST.aprime = s.st.aprime;
  document.getElementById('caseViewInput').value = s.st.mode;
  document.getElementById('buildAltitudeInput').checked = s.st.alt;
  document.getElementById('highlightInput').checked = s.st.hl;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.nar;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

document.addEventListener('fig-resize', function () { render(); });

/* ── init ──────────────────────────────────────────────────────── */
goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

